      const p = (cs[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        const isD = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        take(); take()
        if (isD(cs[i])) run(isD)
        else bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { take(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) { take(); run(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { take(); take(); run(isDigit) }
        }
      }
      if (bad || isIdent(cs[i])) {
        while (i < n && isIdent(cs[i])) take()
        throw new ScanError(sl, sc, `invalid number ${s}`)
      }
      add('number', s, sl, sc)
      continue
    }
    if (c === '"') {
      advance()
      let body = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const bl = line, bc = col
        const d = advance()
        if (d === '"') break
        if (d === '\n') throw new ScanError(bl, bc, 'newline in string')
        if (d !== '\\') { body += d; continue }
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = advance()
        const invalid = () => new ScanError(bl, bc, `invalid escape \\${e}`)
        if (e === 'n') body += '\n'
        else if (e === 't') body += '\t'
        else if (e === 'r') body += '\r'
        else if (e === '\\') body += '\\'
        else if (e === '"') body += '"'
        else if (e === '0') body += '\0'
        else if (e === 'x') {
          let h = ''
          for (let k = 0; k < 2; k++) {
            if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
            if (!isHex(cs[i])) throw invalid()
            h += advance()
          }
          body += String.fromCharCode(parseInt(h, 16))
        } else if (e === 'u') {
          if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
          if (cs[i] !== '{') throw invalid()
          advance()
          let h = ''
          for (;;) {
            if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
            if (cs[i] === '}') break
            if (!isHex(cs[i])) throw invalid()
            h += advance()
          }
          advance()
          if (h === '' || parseInt(h, 16) > 0x10ffff) throw invalid()
          body += String.fromCodePoint(parseInt(h, 16))
        } else throw invalid()
      }
      add('string', JSON.stringify(body), sl, sc)
      continue
    }
    const two = c + (cs[i + 1] || '')
    if (PUNCT2.has(two)) { advance(); advance(); add('punct', two, sl, sc); continue }
    if (PUNCT1.has(c)) { advance(); add('punct', c, sl, sc); continue }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

