  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const text = readFileSync(0, 'utf8')
  let tokens
  try {
    tokens = scan(text)
  } catch (err) {
    if (!(err instanceof ScanError)) throw err
    process.stderr.write(`error: ${err.line}:${err.col}: ${err.message}\n`)
    process.exit(2)
  }
  let out = ''
  if (args[0] === 'tokens') {
    for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
